CREATE TABLE IF NOT EXISTS face_enrollments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,provider TEXT NOT NULL,provider_subject_id TEXT,template_version TEXT NOT NULL DEFAULT 'v1',status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('PENDING','ACTIVE','REVOKED')),consent_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id));
CREATE TABLE IF NOT EXISTS face_verification_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_users(id),attendance_session_id UUID REFERENCES attendance_sessions(id),provider TEXT NOT NULL,verification_id TEXT,face_match BOOLEAN NOT NULL DEFAULT false,liveness_passed BOOLEAN NOT NULL DEFAULT false,confidence NUMERIC(6,5),status TEXT NOT NULL CHECK(status IN ('PASS','FAIL')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_face_events_user ON face_verification_events(user_id);CREATE INDEX IF NOT EXISTS idx_face_events_session ON face_verification_events(attendance_session_id);
